 const target=track=>{if(typeof track!=='string')return null;if(track.startsWith('letters:')){const block=blocks.find(block=>block.id===track.slice(8));return block?{kind:'letters',track,block:block.id}:null;}if(track==='sentences:basics'&&content.sentenceActivities?.length)return {kind:'sentences',track};if(track==='instructions:basics'&&content.instructionActivities?.length)return {kind:'instructions',track};const pack=track==='words'?'first':track.startsWith('words:')?track.slice(6):null;return pack&&packs.some(row=>row.id===pack)?{kind:'words',track:pack==='first'?'words':'words:'+pack,pack}:null;};
 for(const session of Array.isArray(sessions)?sessions:[]){const choice=target(session?.track);if(choice&&!session.done&&/^[a-f0-9]{16,64}$/.test(session.token||'')&&Number.isInteger(session.step)&&Number.isInteger(session.total)&&session.step>=0&&session.step<session.total&&session.total<=12)return {...choice,kind:'resume',reason:'resume',token:session.token,step:session.step,total:session.total};}
 const review=new Set();for(const row of Array.isArray(evidence.practice)?evidence.practice:[]){const skillOK=row?.item?.startsWith('letter:')?['letter-reading.letter','letter-name.letter'].includes(row.skill):row?.skill==='spelling.recall';if(skillOK&&validItems.has(row.item)&&seen.has(row.item)&&Number.isFinite(row.errors)&&row.errors>=2&&Number.isFinite(row.errorDays)&&row.errorDays>=2&&Number.isFinite(row.independent)&&row.independent>=0&&row.independent<3)review.add(row.item);}
 const choices=[...blocks.map(block=>({...target('letters:'+block.id),items:block.letters.map(id=>'letter:'+id)})),...packs.map(pack=>({...target(pack.id==='first'?'words':'words:'+pack.id),items:pack.words.map(id=>'word:'+id)}))].filter(choice=>choice.items.length&&choice.items.every(item=>validItems.has(item)));
