 const nextLetters=choices.find(choice=>choice.kind==='letters'&&choice.items.some(item=>!seen.has(item))),nextWords=choices.find(choice=>choice.kind==='words'&&choice.items.some(item=>!seen.has(item)));
 if(nextLetters||nextWords){const lettersSeen=letters.filter(letter=>seen.has('letter:'+letter.id)).length,wordsSeen=words.filter(word=>seen.has('word:'+word.id)).length,choice=!nextWords||nextLetters&&lettersSeen<=wordsSeen?nextLetters:nextWords,{items,...result}=choice;return {...result,reason:'new'};}
