 function canonicalGuest(s){const next={...s,helped:Boolean(s.helped),hint:Number.isInteger(s.hint)?Math.max(0,Math.min(2,s.hint)):0,errors:Number.isInteger(s.errors)?Math.max(0,Math.min(1000,s.errors)):0};next.plan=s.plan.map(q=>{if(q.item.startsWith('sentence:'))return activityQuestion('sentences',content.sentenceActivities.find(row=>'sentence:'+row.id===q.item),q);if(q.item.startsWith('instruction:'))return activityQuestion('instructions',content.instructionActivities.find(row=>'instruction:'+row.id===q.item),q);if(q.item.startsWith('letter:')){const id=q.item.slice(7),l=content.letters.find(l=>l.id===id),pair=content.blocks.find(b=>b.letters.includes(id))?.letters||[id,'A'];return {item:q.item,letter:l,answer:id,choices:canonicalLetterChoice(q.choices,pair),choiceSets:{reading:canonicalLetterChoice(q.choiceSets?.reading??q.choices,pair),listening:canonicalLetterChoice(q.choiceSets?.listening??q.choices,pair)},mode:q.mode==='model'?'model':'letter',topic:'nomi delle lettere'};}const word=content.words.find(w=>w.id===q.item.slice(5));return {item:q.item,word,answer:word.id,choices:canonicalWordChoices(q.choices,word,s.track),mode:['model','recognize','build','recall','phrase'].includes(q.mode)?q.mode:'model',topic:word.topic};});next.done=Boolean(s.done)&&next.step===next.plan.length;return next;}
