 const phonicsWord=word=>'<span class="phonicsInitial">'+esc(word.id[0])+'</span>'+esc(word.id.slice(1));
 function phonicsReason(q,selected){if(q.kind==='concept')return q.answer==='name'?'Per lo spelling diciamo i nomi delle lettere, una per una. Il nome non è il piccolo suono nella parola.':'Per leggere insieme ascoltiamo i suoni nella parola. Il nome della lettera serve allo spelling.';if(q.kind==='gap')return q.word.id+' comincia con la lettera '+q.group.letter+'. Guardiamo il suo inizio e pronunciamo la parola con un adulto.';const chosen=content.words.find(w=>w.id===selected);return (chosen?chosen.id+' comincia con '+chosen.id[0].toUpperCase()+'. ':'')+'Qui cerchiamo una parola che inizi con '+q.group.letter+', come '+q.modelWord.id+'. Confrontiamo l’inizio con un adulto.';}
 function showPhonicsHint(){const q=session.question,box=target().querySelector('#phonicsHintModel');if(!box||!session.hint)return;let text=q.kind==='concept'?(session.hint===2?phonicsReason(q):q.answer==='name'?'Spelling: raccontiamo come si scrive, lettera per lettera.':'Leggiamo insieme: ascoltiamo la parola e il suo inizio.'):session.hint===1?'La lettera iniziale è '+q.group.letter+'.':q.word.id+' · '+q.word.meaning;box.innerHTML='<p>Guardiamo insieme.</p><p class="trainingWord">'+esc(text)+'</p>';target().querySelector('#phonicsHint').textContent=session.hint===1?'💡 Mostrami il modello':'💡 Il modello resta disponibile';}
 function updatePhonicsAudio(){const note=target()?.querySelector('#phonicsVoiceStatus');if(note)note.textContent=voice('en-GB')?'La voce legge parole intere; il suono iniziale lo modellate con un adulto.':'Voce locale non disponibile: puoi continuare leggendo con un adulto.';const wordAudio=target()?.querySelector('#phonicsWordAudio');if(wordAudio&&phonicsAnswered)wordAudio.disabled=true;const q=session?.question,button=target()?.querySelector('#phonicsNameAudio');if(button&&q?.group)button.disabled=phonicsAnswered||!verified(q.group.letter);}
