 async function hintPhonics(){if(!session||busy||phonicsAnswered)return;phonicsHelped=true;const oldStep=session.step,level=Math.min(2,(session.hint||0)+1);session.hint=level;showPhonicsHint();const data=await act(async owner=>{if(owner)return account.request('phonics-hint',{profile:owner,token:session.token,step:oldStep,level});const g=phonicsGuestRead(),s=g.sessions[session.lesson];if(!s||s.token!==session.token)throw Error('Riprendi il percorso confermato.');if(s.step!==oldStep)return {replayed:true,session:phonicsGuestSnapshot(s)};s.hint=Math.max(s.hint,level);phonicsGuestSave(g);return {session:phonicsGuestSnapshot(s)};},openPhonics);if(data?.replayed)drawPhonics();else if(data)showPhonicsHint();}
