 const skillNames={'sentence.compose':'Comporre una frase','heard-instruction.meaning':'Consegna ascoltata → significato','instruction-reading.meaning':'Consegna letta → significato','letter-name.letter':'Nome inglese ascoltato → lettera','letter-reading.letter':'Lettera vista → lettera','heard-word.meaning':'Parola ascoltata → significato','word-reading.meaning':'Parola letta → significato','spelling.compose':'Composizione con modello','spelling.recall':'Scrittura senza modello / supporto facoltativo','phrase.match':'Piccole frasi','model.explore':'Esplorazione con modello'};
